def test_rejects_a_corrupted_pool(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=4)
    assert run_gate(pool, empty_registry(tmp_path), POOL_SHA256="0" * 64).returncode != 0


def test_accepts_a_source_at_weight_zero(tmp_path):
    # The builder records every source, including one whose weight is zero.
    pool = write_pool(tmp_path, {"swe_smith": 6, "swe_rebench": 4, "r2e_gym": 0}, total=10)
    assert run_gate(pool, empty_registry(tmp_path)).returncode == 0


def test_accepts_a_legacy_manifest_that_omits_zero_sources(tmp_path):
    # Builder v1 wrote only the sources it gave a positive weight.
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=4)
    manifest = json.loads((pool / "manifest.json").read_text(encoding="utf-8"))
    manifest["source_weights"] = {"swe_smith": 100.0, "swe_rebench": 0.0, "r2e_gym": 0.0}
    manifest["excluded_instance_counts"] = {"swe_smith": 0}
    (pool / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    assert run_gate(pool, empty_registry(tmp_path)).returncode == 0


def test_rejects_a_manifest_with_no_total(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=None)
    result = run_gate(pool, empty_registry(tmp_path))
    assert result.returncode != 0
    assert "total_queries" in result.stdout


def test_rejects_a_non_integer_total(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=4.5)
    assert run_gate(pool, empty_registry(tmp_path)).returncode != 0


def test_rejects_a_manifest_whose_digest_does_not_match_the_file(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=4)
    manifest = json.loads((pool / "manifest.json").read_text(encoding="utf-8"))
    manifest["sha256"] = "0" * 64
    (pool / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    assert run_gate(pool, empty_registry(tmp_path)).returncode != 0


def test_rejects_a_registry_with_a_duplicate_entry(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 4}, total=4)
    registry = tmp_path / "registry.json"
    entry = {"source": "swe_smith", "instance_id": "swe_smith__missing"}
    registry.write_text(json.dumps({"selected": [entry, dict(entry)]}) + "\n", encoding="utf-8")
    manifest = json.loads((pool / "manifest.json").read_text(encoding="utf-8"))
    manifest["excluded_instance_counts"] = {"swe_smith": 1}
    (pool / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    assert run_gate(pool, registry).returncode != 0


def test_rejects_counts_that_are_not_the_weight_allocation(tmp_path):
    pool = write_pool(tmp_path, {"swe_smith": 9, "swe_rebench": 1}, total=10)
    manifest = json.loads((pool / "manifest.json").read_text(encoding="utf-8"))
    manifest["source_weights"] = {"swe_smith": 50.0, "swe_rebench": 50.0}
    manifest["excluded_instance_counts"] = {"swe_smith": 0, "swe_rebench": 0}
    (pool / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    assert run_gate(pool, empty_registry(tmp_path)).returncode != 0

